import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"梦游天姥吟留别","description":"","frontmatter":{"title":"梦游天姥吟留别","date":"2026-11-23T00:00:00.000Z","seq":9,"categories":["美文","唐诗三百首"],"collection":"《唐诗三百首 · 七言古诗》","tags":["唐诗三百首","唐"],"poem":true,"poem_quote":false,"author":"李白","source_book":"唐诗三百首"},"headers":[],"relativePath":"blogs/唐诗三百首·七言古诗/梦游天姥吟留别.md","filePath":"blogs/唐诗三百首·七言古诗/梦游天姥吟留别.md"}'),o={name:"blogs/唐诗三百首·七言古诗/梦游天姥吟留别.md"};function l(c,a,n,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="梦游天姥吟留别" tabindex="-1">梦游天姥吟留别 <a class="header-anchor" href="#梦游天姥吟留别" aria-label="Permalink to &quot;梦游天姥吟留别&quot;">​</a></h1><p class="poem-meta">唐 · 李白　·　七言古诗</p><div class="poem"><p class="poem-stanza">海客谈瀛洲，烟涛微茫信难求；</p><p class="poem-stanza">越人语天姥，云霞明灭或可睹。</p><p class="poem-stanza">天姥连天向天横，势拔五岳掩赤城。</p><p class="poem-stanza">天台四万八千丈，对此欲倒东南倾。(四万 一作：一万)</p><p class="poem-stanza">我欲因之梦吴越，一夜飞度镜湖月。(度 通：渡)</p><p class="poem-stanza">湖月照我影，送我至剡溪。</p><p class="poem-stanza">谢公宿处今尚在，渌水荡漾清猿啼。</p><p class="poem-stanza">脚著谢公屐，身登青云梯。</p><p class="poem-stanza">半壁见海日，空中闻天鸡。</p><p class="poem-stanza">千岩万转路不定，迷花倚石忽已暝。</p><p class="poem-stanza">熊咆龙吟殷岩泉，栗深林兮惊层巅。</p><p class="poem-stanza">云青青兮欲雨，水澹澹兮生烟。</p><p class="poem-stanza">列缺霹雳，丘峦崩摧。</p><p class="poem-stanza">洞天石扉，訇然中开。</p><p class="poem-stanza">青冥浩荡不见底，日月照耀金银台。</p><p class="poem-stanza">霓为衣兮风为马，云之君兮纷纷而来下。</p><p class="poem-stanza">虎鼓瑟兮鸾回车，仙之人兮列如麻。</p><p class="poem-stanza">忽魂悸以魄动，恍惊起而长嗟。</p><p class="poem-stanza">惟觉时之枕席，失向来之烟霞。</p><p class="poem-stanza">世间行乐亦如此，古来万事东流水。</p><p class="poem-stanza">别君去兮何时还？且放白鹿青崖间，须行即骑访名山。</p><p class="poem-stanza">安能摧眉折腰事权贵，使我不得开心颜!</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
